WITH session_totals AS (SELECT session_id, COUNT(CASE WHEN page = '/checkout' THEN 1 END) AS checkout_count, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec FROM web_events GROUP BY session_id) SELECT s.id, s.device, s.customer_id, st.checkout_count, st.stddev_duration_sec FROM sessions s LEFT JOIN session_totals st ON s.id = st.session_id WHERE st.checkout_count > 5 ORDER BY id DESC, stddev_duration_sec DESC;
